const ACTS_CHAPTERS = {"1":{"chapter":1,"translation":"NKJV","verses":[{"v":1,"text":"The former account I made, O Theophilus, of all that Jesus began both to do and teach,","heading":"Prologue"},{"v":2,"text":"until the day in which He was taken up, after He through the Holy Spirit had given commandments to the apostles whom He had chosen,","heading":null},{"v":3,"text":"to whom He also presented Himself alive after His suffering by many infallible proofs, being seen by them during forty days and speaking of the things pertaining to the kingdom of God.","heading":null},{"v":4,"text":"And being assembled together with them, He commanded them not to depart from Jerusalem, but to wait for the Promise of the Father, “which,” He said, “you have heard from Me;","heading":"The Holy Spirit Promised"},{"v":5,"text":"for John truly baptized with water, but you shall be baptized with the Holy Spirit not many days from now.”","heading":null},{"v":6,"text":"Therefore, when they had come together, they asked Him, saying, “Lord, will You at this time restore the kingdom to Israel?”","heading":null},{"v":7,"text":"And He said to them, “It is not for you to know times or seasons which the Father has put in His own authority.","heading":null},{"v":8,"text":"But you shall receive power when the Holy Spirit has come upon you; and you shall be witnesses to Me in Jerusalem, and in all Judea and Samaria, and to the end of the earth.”","heading":null},{"v":9,"text":"Now when He had spoken these things, while they watched, He was taken up, and a cloud received Him out of their sight.","heading":"Jesus Ascends to Heaven"},{"v":10,"text":"And while they looked steadfastly toward heaven as He went up, behold, two men stood by them in white apparel,","heading":null},{"v":11,"text":"who also said, “Men of Galilee, why do you stand gazing up into heaven? This same Jesus, who was taken up from you into heaven, will so come in like manner as you saw Him go into heaven.”","heading":null},{"v":12,"text":"Then they returned to Jerusalem from the mount called Olivet, which is near Jerusalem, a Sabbath day’s journey.","heading":"The Upper Room Prayer Meeting"},{"v":13,"text":"And when they had entered, they went up into the upper room where they were staying: Peter, James, John, and Andrew; Philip and Thomas; Bartholomew and Matthew; James the son of Alphaeus and Simon the Zealot; and Judas the son of James.","heading":null},{"v":14,"text":"These all continued with one accord in prayer and supplication, with the women and Mary the mother of Jesus, and with His brothers.","heading":null},{"v":15,"text":"And in those days Peter stood up in the midst of the disciples (altogether the number of names was about a hundred and twenty), and said,","heading":"Matthias Chosen"},{"v":16,"text":"“Men and brethren, this Scripture had to be fulfilled, which the Holy Spirit spoke before by the mouth of David concerning Judas, who became a guide to those who arrested Jesus;","heading":null},{"v":17,"text":"for he was numbered with us and obtained a part in this ministry.”","heading":null},{"v":18,"text":"(Now this man purchased a field with the wages of iniquity; and falling headlong, he burst open in the middle and all his entrails gushed out.","heading":null},{"v":19,"text":"And it became known to all those dwelling in Jerusalem; so that field is called in their own language, Akel Dama, that is, Field of Blood.)","heading":null},{"v":20,"text":"“For it is written in the Book of Psalms: ‘Let his dwelling place be desolate, And let no one live in it’; and, ‘Let another take his office.’","heading":null},{"v":21,"text":"“Therefore, of these men who have accompanied us all the time that the Lord Jesus went in and out among us,","heading":null},{"v":22,"text":"beginning from the baptism of John to that day when He was taken up from us, one of these must become a witness with us of His resurrection.”","heading":null},{"v":23,"text":"And they proposed two: Joseph called Barsabas, who was surnamed Justus, and Matthias.","heading":null},{"v":24,"text":"And they prayed and said, “You, O Lord, who know the hearts of all, show which of these two You have chosen","heading":null},{"v":25,"text":"to take part in this ministry and apostleship from which Judas by transgression fell, that he might go to his own place.”","heading":null},{"v":26,"text":"And they cast their lots, and the lot fell on Matthias. And he was numbered with the eleven apostles.","heading":null}],"days":[{"day":1,"week":1,"ref":"Acts 1:1-8","title":"The Holy Spirit Promised","start":1,"end":8},{"day":2,"week":1,"ref":"Acts 1:9-14","title":"Jesus Ascends to Heaven; Upper Room Prayer Meeting","start":9,"end":14},{"day":3,"week":1,"ref":"Acts 1:15-20","title":"Matthias Chosen","start":15,"end":20},{"day":4,"week":1,"ref":"Acts 1:21-26","title":"Matthias Chosen (continued)","start":21,"end":26}]},"2":{"chapter":2,"translation":"NKJV","verses":[{"v":1,"text":"When the Day of Pentecost had fully come, they were all with one accord in one place.","heading":null},{"v":2,"text":"And suddenly there came a sound from heaven, as of a rushing mighty wind, and it filled the whole house where they were sitting.","heading":null},{"v":3,"text":"Then there appeared to them divided tongues, as of fire, and one sat upon each of them.","heading":null},{"v":4,"text":"And they were all filled with the Holy Spirit and began to speak with other tongues, as the Spirit gave them utterance.","heading":null},{"v":5,"text":"And there were dwelling in Jerusalem Jews, devout men, from every nation under heaven.","heading":"The Crowd’s Response"},{"v":6,"text":"And when this sound occurred, the multitude came together, and were confused, because everyone heard them speak in his own language.","heading":null},{"v":7,"text":"Then they were all amazed and marveled, saying to one another, “Look, are not all these who speak Galileans?","heading":null},{"v":8,"text":"And how is it that we hear, each in our own language in which we were born?","heading":null},{"v":9,"text":"Parthians and Medes and Elamites, those dwelling in Mesopotamia, Judea and Cappadocia, Pontus and Asia,","heading":null},{"v":10,"text":"Phrygia and Pamphylia, Egypt and the parts of Libya adjoining Cyrene, visitors from Rome, both Jews and proselytes,","heading":null},{"v":11,"text":"Cretans and Arabs—we hear them speaking in our own tongues the wonderful works of God.”","heading":null},{"v":12,"text":"So they were all amazed and perplexed, saying to one another, “Whatever could this mean?”","heading":null},{"v":13,"text":"Others mocking said, “They are full of new wine.”","heading":null},{"v":14,"text":"But Peter, standing up with the eleven, raised his voice and said to them, “Men of Judea and all who dwell in Jerusalem, let this be known to you, and heed my words.","heading":"Peter’s Sermon"},{"v":15,"text":"For these are not drunk, as you suppose, since it is only the third hour of the day.","heading":null},{"v":16,"text":"But this is what was spoken by the prophet Joel:","heading":null},{"v":17,"text":"‘And it shall come to pass in the last days, says God, That I will pour out of My Spirit on all flesh; Your sons and your daughters shall prophesy, Your young men shall see visions, Your old men shall dream dreams.","heading":null},{"v":18,"text":"And on My menservants and on My maidservants I will pour out My Spirit in those days; And they shall prophesy.","heading":null},{"v":19,"text":"I will show wonders in heaven above And signs in the earth beneath: Blood and fire and vapor of smoke.","heading":null},{"v":20,"text":"The sun shall be turned into darkness, And the moon into blood, Before the coming of the great and awesome day of the LORD.","heading":null},{"v":21,"text":"And it shall come to pass That whoever calls on the name of the LORD Shall be saved.’","heading":null},{"v":22,"text":"“Men of Israel, hear these words: Jesus of Nazareth, a Man attested by God to you by miracles, wonders, and signs which God did through Him in your midst, as you yourselves also know—","heading":null},{"v":23,"text":"Him, being delivered by the determined purpose and foreknowledge of God, you have taken by lawless hands, have crucified, and put to death;","heading":null},{"v":24,"text":"whom God raised up, having loosed the pains of death, because it was not possible that He should be held by it.","heading":null},{"v":25,"text":"For David says concerning Him: ‘I foresaw the LORD always before my face, For He is at my right hand, that I may not be shaken.","heading":null},{"v":26,"text":"Therefore my heart rejoiced, and my tongue was glad; Moreover my flesh also will rest in hope.","heading":null},{"v":27,"text":"For You will not leave my soul in Hades, Nor will You allow Your Holy One to see corruption.","heading":null},{"v":28,"text":"You have made known to me the ways of life; You will make me full of joy in Your presence.’","heading":null},{"v":29,"text":"“Men and brethren, let me speak freely to you of the patriarch David, that he is both dead and buried, and his tomb is with us to this day.","heading":null},{"v":30,"text":"Therefore, being a prophet, and knowing that God had sworn with an oath to him that of the fruit of his body, according to the flesh, He would raise up the Christ to sit on his throne,","heading":null},{"v":31,"text":"he, foreseeing this, spoke concerning the resurrection of the Christ, that His soul was not left in Hades, nor did His flesh see corruption.","heading":null},{"v":32,"text":"This Jesus God has raised up, of which we are all witnesses.","heading":null},{"v":33,"text":"Therefore being exalted to the right hand of God, and having received from the Father the promise of the Holy Spirit, He poured out this which you now see and hear.","heading":null},{"v":34,"text":"“For David did not ascend into the heavens, but he says himself: ‘The LORD said to my Lord, “Sit at My right hand,","heading":null},{"v":35,"text":"Till I make Your enemies Your footstool.” ’","heading":null},{"v":36,"text":"“Therefore let all the house of Israel know assuredly that God has made this Jesus, whom you crucified, both Lord and Christ.”","heading":null},{"v":37,"text":"Now when they heard this, they were cut to the heart, and said to Peter and the rest of the apostles, “Men and brethren, what shall we do?”","heading":null},{"v":38,"text":"Then Peter said to them, “Repent, and let every one of you be baptized in the name of Jesus Christ for the remission of sins; and you shall receive the gift of the Holy Spirit.","heading":null},{"v":39,"text":"For the promise is to you and to your children, and to all who are afar off, as many as the Lord our God will call.”","heading":null},{"v":40,"text":"And with many other words he testified and exhorted them, saying, “Be saved from this perverse generation.”","heading":"A Vital Church Grows"},{"v":41,"text":"Then those who gladly received his word were baptized; and that day about three thousand souls were added to them.","heading":null},{"v":42,"text":"And they continued steadfastly in the apostles’ doctrine and fellowship, in the breaking of bread, and in prayers.","heading":null},{"v":43,"text":"Then fear came upon every soul, and many wonders and signs were done through the apostles.","heading":null},{"v":44,"text":"Now all who believed were together, and had all things in common,","heading":null},{"v":45,"text":"and sold their possessions and goods, and divided them among all, as anyone had need.","heading":null},{"v":46,"text":"So continuing daily with one accord in the temple, and breaking bread from house to house, they ate their food with gladness and simplicity of heart,","heading":null},{"v":47,"text":"praising God and having favor with all the people. And the Lord added to the church daily those who were being saved.","heading":null}],"days":[{"day":5,"week":1,"ref":"Acts 2:1-4","title":"Coming of the Holy Spirit","start":1,"end":4},{"day":6,"week":2,"ref":"Acts 2:5-13","title":"The Crowd’s Response","start":5,"end":13},{"day":7,"week":2,"ref":"Acts 2:14-21","title":"Peter’s Sermon","start":14,"end":21},{"day":8,"week":2,"ref":"Acts 2:22-28","title":"Peter’s Sermon (continued)","start":22,"end":28},{"day":9,"week":2,"ref":"Acts 2:29-39","title":"Peter’s Sermon (continued)","start":29,"end":39},{"day":10,"week":2,"ref":"Acts 2:40-47","title":"A Vital Church Grows","start":40,"end":47}]},"3":{"chapter":3,"translation":"NKJV","verses":[{"v":1,"text":"Now Peter and John went up together to the temple at the hour of prayer, the ninth hour.","heading":null},{"v":2,"text":"And a certain man lame from his mother’s womb was carried, whom they laid daily at the gate of the temple which is called Beautiful, to ask alms from those who entered the temple;","heading":null},{"v":3,"text":"who, seeing Peter and John about to go into the temple, asked for alms.","heading":null},{"v":4,"text":"And fixing his eyes on him, with John, Peter said, “Look at us.”","heading":null},{"v":5,"text":"So he gave them his attention, expecting to receive something from them.","heading":null},{"v":6,"text":"Then Peter said, “Silver and gold I do not have, but what I do have I give you: In the name of Jesus Christ of Nazareth, rise up and walk.”","heading":null},{"v":7,"text":"And he took him by the right hand and lifted him up, and immediately his feet and ankle bones received strength.","heading":null},{"v":8,"text":"So he, leaping up, stood and walked and entered the temple with them—walking, leaping, and praising God.","heading":null},{"v":9,"text":"And all the people saw him walking and praising God.","heading":null},{"v":10,"text":"Then they knew that it was he who sat begging alms at the Beautiful Gate of the temple; and they were filled with wonder and amazement at what had happened to him.","heading":null},{"v":11,"text":"Now as the lame man who was healed held on to Peter and John, all the people ran together to them in the porch which is called Solomon’s, greatly amazed.","heading":"Preaching in Solomon’s Portico"},{"v":12,"text":"So when Peter saw it, he responded to the people: “Men of Israel, why do you marvel at this? Or why look so intently at us, as though by our own power or godliness we had made this man walk?","heading":null},{"v":13,"text":"The God of Abraham, Isaac, and Jacob, the God of our fathers, glorified His Servant Jesus, whom you delivered up and denied in the presence of Pilate, when he was determined to let Him go.","heading":null},{"v":14,"text":"But you denied the Holy One and the Just, and asked for a murderer to be granted to you,","heading":null},{"v":15,"text":"and killed the Prince of life, whom God raised from the dead, of which we are witnesses.","heading":null},{"v":16,"text":"And His name, through faith in His name, has made this man strong, whom you see and know. Yes, the faith which comes through Him has given him this perfect soundness in the presence of you all.","heading":null},{"v":17,"text":"“Yet now, brethren, I know that you did it in ignorance, as did also your rulers.","heading":null},{"v":18,"text":"But those things which God foretold by the mouth of all His prophets, that the Christ would suffer, He has thus fulfilled.","heading":null},{"v":19,"text":"Repent therefore and be converted, that your sins may be blotted out, so that times of refreshing may come from the presence of the Lord,","heading":null},{"v":20,"text":"and that He may send Jesus Christ, who was preached to you before,","heading":null},{"v":21,"text":"whom heaven must receive until the times of restoration of all things, which God has spoken by the mouth of all His holy prophets since the world began.","heading":null},{"v":22,"text":"For Moses truly said to the fathers, ‘The LORD your God will raise up for you a Prophet like me from your brethren. Him you shall hear in all things, whatever He says to you.","heading":null},{"v":23,"text":"And it shall be that every soul who will not hear that Prophet shall be utterly destroyed from among the people.’","heading":null},{"v":24,"text":"Yes, and all the prophets, from Samuel and those who follow, as many as have spoken, have also foretold these days.","heading":null},{"v":25,"text":"You are sons of the prophets, and of the covenant which God made with our fathers, saying to Abraham, ‘And in your seed all the families of the earth shall be blessed.’","heading":null},{"v":26,"text":"To you first, God, having raised up His Servant Jesus, sent Him to bless you, in turning away every one of you from your iniquities.”","heading":null}],"days":[{"day":11,"week":3,"ref":"Acts 3:1-10","title":"A Lame Man Healed","start":1,"end":10},{"day":12,"week":3,"ref":"Acts 3:11-26","title":"Preaching in Solomon’s Portico","start":11,"end":26},{"day":13,"week":3,"ref":"Acts 3:11-26","title":"Preaching in Solomon’s Portico (continued)","start":11,"end":26}]},"4":{"chapter":4,"translation":"NKJV","verses":[{"v":1,"text":"Now as they spoke to the people, the priests, the captain of the temple, and the Sadducees came upon them,","heading":null},{"v":2,"text":"being greatly disturbed that they taught the people and preached in Jesus the resurrection from the dead.","heading":null},{"v":3,"text":"And they laid hands on them, and put them in custody until the next day, for it was already evening.","heading":null},{"v":4,"text":"However, many of those who heard the word believed; and the number of the men came to be about five thousand.","heading":null},{"v":5,"text":"And it came to pass, on the next day, that their rulers, elders, and scribes,","heading":"Addressing the Sanhedrin"},{"v":6,"text":"as well as Annas the high priest, Caiaphas, John, and Alexander, and as many as were of the family of the high priest, were gathered together at Jerusalem.","heading":null},{"v":7,"text":"And when they had set them in the midst, they asked, “By what power or by what name have you done this?”","heading":null},{"v":8,"text":"Then Peter, filled with the Holy Spirit, said to them, “Rulers of the people and elders of Israel:","heading":null},{"v":9,"text":"If we this day are judged for a good deed done to a helpless man, by what means he has been made well,","heading":null},{"v":10,"text":"let it be known to you all, and to all the people of Israel, that by the name of Jesus Christ of Nazareth, whom you crucified, whom God raised from the dead, by Him this man stands here before you whole.","heading":null},{"v":11,"text":"This is the ‘stone which was rejected by you builders, which has become the chief cornerstone.’","heading":null},{"v":12,"text":"Nor is there salvation in any other, for there is no other name under heaven given among men by which we must be saved.”","heading":null},{"v":13,"text":"Now when they saw the boldness of Peter and John, and perceived that they were uneducated and untrained men, they marveled. And they realized that they had been with Jesus.","heading":"The Name of Jesus Forbidden"},{"v":14,"text":"And seeing the man who had been healed standing with them, they could say nothing against it.","heading":null},{"v":15,"text":"But when they had commanded them to go aside out of the council, they conferred among themselves,","heading":null},{"v":16,"text":"saying, “What shall we do to these men? For, indeed, that a notable miracle has been done through them is evident to all who dwell in Jerusalem, and we cannot deny it.","heading":null},{"v":17,"text":"But so that it spreads no further among the people, let us severely threaten them, that from now on they speak to no man in this name.”","heading":null},{"v":18,"text":"So they called them and commanded them not to speak at all nor teach in the name of Jesus.","heading":null},{"v":19,"text":"But Peter and John answered and said to them, “Whether it is right in the sight of God to listen to you more than to God, you judge.","heading":null},{"v":20,"text":"For we cannot but speak the things which we have seen and heard.”","heading":null},{"v":21,"text":"So when they had further threatened them, they let them go, finding no way of punishing them, because of the people, since they all glorified God for what had been done.","heading":null},{"v":22,"text":"For the man was over forty years old on whom this miracle of healing had been performed.","heading":null},{"v":23,"text":"And being let go, they went to their own companions and reported all that the chief priests and elders had said to them.","heading":"Prayer for Boldness"},{"v":24,"text":"So when they heard that, they raised their voice to God with one accord and said: “Lord, You are God, who made heaven and earth and the sea, and all that is in them,","heading":null},{"v":25,"text":"who by the mouth of Your servant David have said: ‘Why did the nations rage, And the people plot vain things?","heading":null},{"v":26,"text":"The kings of the earth took their stand, And the rulers were gathered together Against the LORD and against His Christ.’","heading":null},{"v":27,"text":"“For truly against Your holy Servant Jesus, whom You anointed, both Herod and Pontius Pilate, with the Gentiles and the people of Israel, were gathered together","heading":null},{"v":28,"text":"to do whatever Your hand and Your purpose determined before to be done.","heading":null},{"v":29,"text":"Now, Lord, look on their threats, and grant to Your servants that with all boldness they may speak Your word,","heading":null},{"v":30,"text":"by stretching out Your hand to heal, and that signs and wonders may be done through the name of Your holy Servant Jesus.”","heading":null},{"v":31,"text":"And when they had prayed, the place where they were assembled together was shaken; and they were all filled with the Holy Spirit, and they spoke the word of God with boldness.","heading":null},{"v":32,"text":"Now the multitude of those who believed were of one heart and one soul; neither did anyone say that any of the things he possessed was his own, but they had all things in common.","heading":"Sharing in All Things"},{"v":33,"text":"And with great power the apostles gave witness to the resurrection of the Lord Jesus. And great grace was upon them all.","heading":null},{"v":34,"text":"Nor was there anyone among them who lacked; for all who were possessors of lands or houses sold them, and brought the proceeds of the things that were sold,","heading":null},{"v":35,"text":"and laid them at the apostles’ feet; and they distributed to each as anyone had need.","heading":null},{"v":36,"text":"And Joses, who was also named Barnabas by the apostles (which is translated Son of Encouragement), a Levite of the country of Cyprus,","heading":null},{"v":37,"text":"having land, sold it, and brought the money and laid it at the apostles’ feet.","heading":null}],"days":[{"day":14,"week":3,"ref":"Acts 4:1-4","title":"Peter and John Arrested","start":1,"end":4},{"day":15,"week":3,"ref":"Acts 4:5-12","title":"Addressing the Sanhedrin","start":5,"end":12},{"day":16,"week":4,"ref":"Acts 4:13-22","title":"The Name of Jesus Forbidden","start":13,"end":22},{"day":17,"week":4,"ref":"Acts 4:23-31","title":"Prayer for Boldness","start":23,"end":31},{"day":18,"week":4,"ref":"Acts 4:32-37","title":"Sharing in All Things","start":32,"end":37}]},"5":{"chapter":5,"translation":"NKJV","verses":[{"v":1,"text":"But a certain man named Ananias, with Sapphira his wife, sold a possession.","heading":null},{"v":2,"text":"And he kept back part of the proceeds, his wife also being aware of it, and brought a certain part and laid it at the apostles’ feet.","heading":null},{"v":3,"text":"But Peter said, “Ananias, why has Satan filled your heart to lie to the Holy Spirit and keep back part of the price of the land for yourself?","heading":null},{"v":4,"text":"While it remained, was it not your own? And after it was sold, was it not in your own control? Why have you conceived this thing in your heart? You have not lied to men but to God.”","heading":null},{"v":5,"text":"Then Ananias, hearing these words, fell down and breathed his last. So great fear came upon all those who heard these things.","heading":null},{"v":6,"text":"And the young men arose and wrapped him up, carried him out, and buried him.","heading":null},{"v":7,"text":"Now it was about three hours later when his wife came in, not knowing what had happened.","heading":null},{"v":8,"text":"And Peter answered her, “Tell me whether you sold the land for so much?” She said, “Yes, for so much.”","heading":null},{"v":9,"text":"Then Peter said to her, “How is it that you have agreed together to test the Spirit of the Lord? Look, the feet of those who have buried your husband are at the door, and they will carry you out.”","heading":null},{"v":10,"text":"Then immediately she fell down at his feet and breathed her last. And the young men came in and found her dead, and carrying her out, buried her by her husband.","heading":null},{"v":11,"text":"So great fear came upon all the church and upon all who heard these things.","heading":null},{"v":12,"text":"And through the hands of the apostles many signs and wonders were done among the people. And they were all with one accord in Solomon’s Porch.","heading":"Continuing Power in the Church"},{"v":13,"text":"Yet none of the rest dared join them, but the people esteemed them highly.","heading":null},{"v":14,"text":"And believers were increasingly added to the Lord, multitudes of both men and women,","heading":null},{"v":15,"text":"so that they brought the sick out into the streets and laid them on beds and couches, that at least the shadow of Peter passing by might fall on some of them.","heading":null},{"v":16,"text":"Also a multitude gathered from the surrounding cities to Jerusalem, bringing sick people and those who were tormented by unclean spirits, and they were all healed.","heading":null},{"v":17,"text":"Then the high priest rose up, and all those who were with him (which is the sect of the Sadducees), and they were filled with indignation,","heading":"Imprisoned Apostles Freed"},{"v":18,"text":"and laid their hands on the apostles and put them in the common prison.","heading":null},{"v":19,"text":"But at night an angel of the Lord opened the prison doors and brought them out, and said,","heading":null},{"v":20,"text":"“Go, stand in the temple and speak to the people all the words of this life.”","heading":null},{"v":21,"text":"And when they heard that, they entered the temple early in the morning and taught. But the high priest and those with him came and called the council together, with all the elders of the children of Israel, and sent to the prison to have them brought.","heading":null},{"v":22,"text":"But when the officers came and did not find them in the prison, they returned and reported,","heading":"Apostles on Trial Again"},{"v":23,"text":"saying, “Indeed we found the prison shut securely, and the guards standing outside before the doors; but when we opened them, we found no one inside!”","heading":null},{"v":24,"text":"Now when the high priest, the captain of the temple, and the chief priests heard these things, they wondered what the outcome would be.","heading":null},{"v":25,"text":"So one came and told them, saying, “Look, the men whom you put in prison are standing in the temple and teaching the people!”","heading":null},{"v":26,"text":"Then the captain went with the officers and brought them without violence, for they feared the people, lest they should be stoned.","heading":null},{"v":27,"text":"And when they had brought them, they set them before the council. And the high priest asked them,","heading":null},{"v":28,"text":"saying, “Did we not strictly command you not to teach in this name? And look, you have filled Jerusalem with your doctrine, and intend to bring this Man’s blood on us!”","heading":null},{"v":29,"text":"But Peter and the other apostles answered and said: “We ought to obey God rather than men.","heading":null},{"v":30,"text":"The God of our fathers raised up Jesus whom you murdered by hanging on a tree.","heading":null},{"v":31,"text":"Him God has exalted to His right hand to be Prince and Savior, to give repentance to Israel and forgiveness of sins.","heading":null},{"v":32,"text":"And we are His witnesses to these things, and so also is the Holy Spirit whom God has given to those who obey Him.”","heading":null},{"v":33,"text":"When they heard this, they were furious and plotted to kill them.","heading":"Gamaliel’s Advice"},{"v":34,"text":"Then one in the council stood up, a Pharisee named Gamaliel, a teacher of the law held in respect by all the people, and commanded them to put the apostles outside for a little while.","heading":null},{"v":35,"text":"And he said to them: “Men of Israel, take heed to yourselves what you intend to do regarding these men.","heading":null},{"v":36,"text":"For some time ago Theudas rose up, claiming to be somebody. A number of men, about four hundred, joined him. He was slain, and all who obeyed him were scattered and came to nothing.","heading":null},{"v":37,"text":"After this man, Judas of Galilee rose up in the days of the census, and drew away many people after him. He also perished, and all who obeyed him were dispersed.","heading":null},{"v":38,"text":"And now I say to you, keep away from these men and let them alone; for if this plan or this work is of men, it will come to nothing;","heading":null},{"v":39,"text":"but if it is of God, you cannot overthrow it—lest you even be found to fight against God.”","heading":null},{"v":40,"text":"And they agreed with him, and when they had called for the apostles and beaten them, they commanded that they should not speak in the name of Jesus, and let them go.","heading":null},{"v":41,"text":"So they departed from the presence of the council, rejoicing that they were counted worthy to suffer shame for His name.","heading":null},{"v":42,"text":"And daily in the temple, and in every house, they did not cease teaching and preaching Jesus as the Christ.","heading":null}],"days":[{"day":19,"week":4,"ref":"Acts 5:1-11","title":"Lying to the Holy Spirit","start":1,"end":11},{"day":20,"week":4,"ref":"Acts 5:12-16","title":"Continuing Power in the Church","start":12,"end":16},{"day":21,"week":5,"ref":"Acts 5:17-21","title":"Imprisoned Apostles Freed","start":17,"end":21},{"day":22,"week":5,"ref":"Acts 5:22-32","title":"Apostles on Trial Again","start":22,"end":32},{"day":23,"week":5,"ref":"Acts 5:33-42","title":"Gamaliel’s Advice","start":33,"end":42}]},"6":{"chapter":6,"translation":"NKJV","verses":[{"v":1,"text":"Now in those days, when the number of the disciples was multiplying, there arose a complaint against the Hebrews by the Hellenists, because their widows were neglected in the daily distribution.","heading":null},{"v":2,"text":"Then the twelve summoned the multitude of the disciples and said, “It is not desirable that we should leave the word of God and serve tables.","heading":null},{"v":3,"text":"Therefore, brethren, seek out from among you seven men of good reputation, full of the Holy Spirit and wisdom, whom we may appoint over this business;","heading":null},{"v":4,"text":"but we will give ourselves continually to prayer and to the ministry of the word.”","heading":null},{"v":5,"text":"And the saying pleased the whole multitude. And they chose Stephen, a man full of faith and the Holy Spirit, and Philip, Prochorus, Nicanor, Timon, Parmenas, and Nicolas, a proselyte from Antioch,","heading":null},{"v":6,"text":"whom they set before the apostles; and when they had prayed, they laid hands on them.","heading":null},{"v":7,"text":"Then the word of God spread, and the number of the disciples multiplied greatly in Jerusalem, and a great many of the priests were obedient to the faith.","heading":null},{"v":8,"text":"And Stephen, full of faith and power, did great wonders and signs among the people.","heading":"Stephen Accused of Blasphemy"},{"v":9,"text":"Then there arose some from what is called the Synagogue of the Freedmen (Cyrenians, Alexandrians, and those from Cilicia and Asia), disputing with Stephen.","heading":null},{"v":10,"text":"And they were not able to resist the wisdom and the Spirit by which he spoke.","heading":null},{"v":11,"text":"Then they secretly induced men to say, “We have heard him speak blasphemous words against Moses and God.”","heading":null},{"v":12,"text":"And they stirred up the people, the elders, and the scribes; and they came upon him, seized him, and brought him to the council.","heading":null},{"v":13,"text":"They also set up false witnesses who said, “This man does not cease to speak blasphemous words against this holy place and the law;","heading":null},{"v":14,"text":"for we have heard him say that this Jesus of Nazareth will destroy this place and change the customs which Moses delivered to us.”","heading":null},{"v":15,"text":"And all who sat in the council, looking steadfastly at him, saw his face as the face of an angel.","heading":null}],"days":[{"day":24,"week":5,"ref":"Acts 6:1-7","title":"Seven Chosen to Serve","start":1,"end":7},{"day":25,"week":5,"ref":"Acts 6:8-15","title":"Stephen Accused of Blasphemy","start":8,"end":15}]},"7":{"chapter":7,"translation":"NKJV","verses":[{"v":1,"text":"Then the high priest said, “Are these things so?”","heading":null},{"v":2,"text":"And he said, “Brethren and fathers, listen: The God of glory appeared to our father Abraham when he was in Mesopotamia, before he dwelt in Haran,","heading":null},{"v":3,"text":"and said to him, ‘Get out of your country and from your relatives, and come to a land that I will show you.’","heading":null},{"v":4,"text":"Then he came out of the land of the Chaldeans and dwelt in Haran. And from there, when his father was dead, He moved him to this land in which you now dwell.","heading":null},{"v":5,"text":"And God gave him no inheritance in it, not even enough to set his foot on. But even when Abraham had no child, He promised to give it to him for a possession, and to his descendants after him.","heading":null},{"v":6,"text":"But God spoke in this way: that his descendants would dwell in a foreign land, and that they would bring them into bondage and oppress them four hundred years.","heading":null},{"v":7,"text":"‘And the nation to whom they will be in bondage I will judge,’ said God, ‘and after that they shall come out and serve Me in this place.’","heading":null},{"v":8,"text":"Then He gave him the covenant of circumcision; and so Abraham begot Isaac and circumcised him on the eighth day; and Isaac begot Jacob, and Jacob begot the twelve patriarchs.","heading":null},{"v":9,"text":"“And the patriarchs, becoming envious, sold Joseph into Egypt. But God was with him","heading":"The Patriarchs in Egypt"},{"v":10,"text":"and delivered him out of all his troubles, and gave him favor and wisdom in the presence of Pharaoh, king of Egypt; and he made him governor over Egypt and all his house.","heading":null},{"v":11,"text":"Now a famine and great trouble came over all the land of Egypt and Canaan, and our fathers found no sustenance.","heading":null},{"v":12,"text":"But when Jacob heard that there was grain in Egypt, he sent out our fathers first.","heading":null},{"v":13,"text":"And the second time Joseph was made known to his brothers, and Joseph’s family became known to the Pharaoh.","heading":null},{"v":14,"text":"Then Joseph sent and called his father Jacob and all his relatives to him, seventy-five people.","heading":null},{"v":15,"text":"So Jacob went down to Egypt; and he died, he and our fathers.","heading":null},{"v":16,"text":"And they were carried back to Shechem and laid in the tomb that Abraham bought for a sum of money from the sons of Hamor, the father of Shechem.","heading":null},{"v":17,"text":"“But when the time of the promise drew near which God had sworn to Abraham, the people grew and multiplied in Egypt","heading":"God Delivers Israel by Moses"},{"v":18,"text":"till another king arose who did not know Joseph.","heading":null},{"v":19,"text":"This man dealt treacherously with our people, and oppressed our forefathers, making them expose their babies, so that they might not live.","heading":null},{"v":20,"text":"At this time Moses was born, and was well pleasing to God; and he was brought up in his father’s house for three months.","heading":null},{"v":21,"text":"But when he was set out, Pharaoh’s daughter took him away and brought him up as her own son.","heading":null},{"v":22,"text":"And Moses was learned in all the wisdom of the Egyptians, and was mighty in words and deeds.","heading":null},{"v":23,"text":"“Now when he was forty years old, it came into his heart to visit his brethren, the children of Israel.","heading":null},{"v":24,"text":"And seeing one of them suffer wrong, he defended and avenged him who was oppressed, and struck down the Egyptian.","heading":null},{"v":25,"text":"For he supposed that his brethren would have understood that God would deliver them by his hand, but they did not understand.","heading":null},{"v":26,"text":"And the next day he appeared to two of them as they were fighting, and tried to reconcile them, saying, ‘Men, you are brethren; why do you wrong one another?’","heading":null},{"v":27,"text":"But he who did his neighbor wrong pushed him away, saying, ‘Who made you a ruler and a judge over us?","heading":null},{"v":28,"text":"Do you want to kill me as you did the Egyptian yesterday?’","heading":null},{"v":29,"text":"Then, at this saying, Moses fled and became a dweller in the land of Midian, where he had two sons.","heading":null},{"v":30,"text":"“And when forty years had passed, an Angel of the Lord appeared to him in a flame of fire in a bush, in the wilderness of Mount Sinai.","heading":null},{"v":31,"text":"When Moses saw it, he marveled at the sight; and as he drew near to observe, the voice of the Lord came to him,","heading":null},{"v":32,"text":"saying, ‘I am the God of your fathers—the God of Abraham, the God of Isaac, and the God of Jacob.’ And Moses trembled and dared not look.","heading":null},{"v":33,"text":"‘Then the LORD said to him, “Take your sandals off your feet, for the place where you stand is holy ground.","heading":null},{"v":34,"text":"I have surely seen the oppression of My people who are in Egypt; I have heard their groaning and have come down to deliver them. And now come, I will send you to Egypt.” ’","heading":null},{"v":35,"text":"“This Moses whom they rejected, saying, ‘Who made you a ruler and a judge?’ is the one God sent to be a ruler and a deliverer by the hand of the Angel who appeared to him in the bush.","heading":null},{"v":36,"text":"He brought them out, after he had shown wonders and signs in the land of Egypt, and in the Red Sea, and in the wilderness forty years.","heading":null},{"v":37,"text":"“This is that Moses who said to the children of Israel, ‘The LORD your God will raise up for you a Prophet like me from your brethren. Him you shall hear.’","heading":"Israel Rebels Against God"},{"v":38,"text":"“This is he who was in the congregation in the wilderness with the Angel who spoke to him on Mount Sinai, and with our fathers, the one who received the living oracles to give to us,","heading":null},{"v":39,"text":"whom our fathers would not obey, but rejected. And in their hearts they turned back to Egypt,","heading":null},{"v":40,"text":"saying to Aaron, ‘Make us gods to go before us; as for this Moses who brought us out of the land of Egypt, we do not know what has become of him.’","heading":null},{"v":41,"text":"And they made a calf in those days, offered sacrifices to the idol, and rejoiced in the works of their own hands.","heading":null},{"v":42,"text":"Then God turned and gave them up to worship the host of heaven, as it is written in the book of the Prophets: ‘Did you offer Me slaughtered animals and sacrifices during forty years in the wilderness, O house of Israel?","heading":null},{"v":43,"text":"You also took up the tabernacle of Moloch, And the star of your god Remphan, Images which you made to worship; And I will carry you away beyond Babylon.’","heading":null},{"v":44,"text":"“Our fathers had the tabernacle of witness in the wilderness, as He appointed, instructing Moses to make it according to the pattern that he had seen,","heading":"God’s True Tabernacle"},{"v":45,"text":"which our fathers, having received it in turn, also brought with Joshua into the land possessed by the Gentiles, whom God drove out before the face of our fathers until the days of David,","heading":null},{"v":46,"text":"who found favor before God and asked to find a dwelling for the God of Jacob.","heading":null},{"v":47,"text":"But Solomon built Him a house.","heading":null},{"v":48,"text":"“However, the Most High does not dwell in temples made with hands, as the prophet says:","heading":null},{"v":49,"text":"‘Heaven is My throne, And earth is My footstool. What house will you build for Me? says the LORD, Or what is the place of My rest?","heading":null},{"v":50,"text":"Has My hand not made all these things?’","heading":null},{"v":51,"text":"“ You stiff-necked and uncircumcised in heart and ears! You always resist the Holy Spirit; as your fathers did, so do you.","heading":"Israel Resists the Holy Spirit"},{"v":52,"text":"Which of the prophets did your fathers not persecute? And they killed those who foretold the coming of the Just One, of whom you now have become the betrayers and murderers,","heading":null},{"v":53,"text":"who have received the law by the direction of angels and have not kept it. ”","heading":null},{"v":54,"text":"When they heard these things they were cut to the heart, and they gnashed at him with their teeth.","heading":"Stephen the Martyr"},{"v":55,"text":"But he, being full of the Holy Spirit, gazed into heaven and saw the glory of God, and Jesus standing at the right hand of God,","heading":null},{"v":56,"text":"and said, “Look! I see the heavens opened and the Son of Man standing at the right hand of God!”","heading":null},{"v":57,"text":"Then they cried out with a loud voice, stopped their ears, and ran at him with one accord;","heading":null},{"v":58,"text":"and they cast him out of the city and stoned him. And the witnesses laid down their clothes at the feet of a young man named Saul.","heading":null},{"v":59,"text":"And they stoned Stephen as he was calling on God and saying, “Lord Jesus, receive my spirit.”","heading":null},{"v":60,"text":"Then he knelt down and cried out with a loud voice, “Lord, do not charge them with this sin.” And when he had said this, he fell asleep.","heading":null}],"days":[{"day":26,"week":6,"ref":"Acts 7:1-8","title":"Stephen’s Address: The Call of Abraham","start":1,"end":8},{"day":27,"week":6,"ref":"Acts 7:9-16","title":"The Patriarchs in Egypt","start":9,"end":16},{"day":28,"week":6,"ref":"Acts 7:17-22","title":"God Delivers Israel by Moses","start":17,"end":22},{"day":29,"week":6,"ref":"Acts 7:23-29","title":"God Delivers Israel by Moses (continued)","start":23,"end":29},{"day":30,"week":6,"ref":"Acts 7:30-36","title":"God Delivers Israel by Moses (continued)","start":30,"end":36},{"day":31,"week":7,"ref":"Acts 7:37-43","title":"Israel Rebels Against God","start":37,"end":43},{"day":32,"week":7,"ref":"Acts 7:44-53","title":"God’s True Tabernacle; Israel Resists the Holy Spirit","start":44,"end":53},{"day":33,"week":7,"ref":"Acts 7:54-60","title":"Stephen the Martyr","start":54,"end":60}]},"8":{"chapter":8,"translation":"NKJV","verses":[{"v":1,"text":"Now Saul was consenting to his death. At that time a great persecution arose against the church which was at Jerusalem; and they were all scattered throughout the regions of Judea and Samaria, except the apostles.","heading":null},{"v":2,"text":"And devout men carried Stephen to his burial, and made great lamentation over him.","heading":null},{"v":3,"text":"As for Saul, he made havoc of the church, entering every house, and dragging off men and women, committing them to prison.","heading":null},{"v":4,"text":"Therefore those who were scattered went everywhere preaching the word.","heading":"Christ Is Preached in Samaria"},{"v":5,"text":"Then Philip went down to the city of Samaria and preached Christ to them.","heading":null},{"v":6,"text":"And the multitudes with one accord heeded the things spoken by Philip, hearing and seeing the miracles which he did.","heading":null},{"v":7,"text":"For unclean spirits, crying with a loud voice, came out of many who were possessed; and many who were paralyzed and lame were healed.","heading":null},{"v":8,"text":"And there was great joy in that city.","heading":null},{"v":9,"text":"But there was a certain man called Simon, who previously practiced sorcery in the city and astonished the people of Samaria, claiming that he was someone great,","heading":"The Sorcerer’s Profession of Faith"},{"v":10,"text":"to whom they all gave heed, from the least to the greatest, saying, “This man is the great power of God.”","heading":null},{"v":11,"text":"And they heeded him because he had astonished them with his sorceries for a long time.","heading":null},{"v":12,"text":"But when they believed Philip as he preached the things concerning the kingdom of God and the name of Jesus Christ, both men and women were baptized.","heading":null},{"v":13,"text":"Then Simon himself also believed; and when he was baptized he continued with Philip, and was amazed, seeing the miracles and signs which were done.","heading":null},{"v":14,"text":"Now when the apostles who were at Jerusalem heard that Samaria had received the word of God, they sent Peter and John to them,","heading":"The Sorcerer’s Sin"},{"v":15,"text":"who, when they had come down, prayed for them that they might receive the Holy Spirit.","heading":null},{"v":16,"text":"For as yet He had fallen upon none of them. They had only been baptized in the name of the Lord Jesus.","heading":null},{"v":17,"text":"Then they laid hands on them, and they received the Holy Spirit.","heading":null},{"v":18,"text":"And when Simon saw that through the laying on of the apostles’ hands the Holy Spirit was given, he offered them money,","heading":null},{"v":19,"text":"saying, “Give me this power also, that anyone on whom I lay hands may receive the Holy Spirit.”","heading":null},{"v":20,"text":"But Peter said to him, “Your money perish with you, because you thought that the gift of God could be purchased with money!","heading":null},{"v":21,"text":"You have neither part nor portion in this matter, for your heart is not right in the sight of God.","heading":null},{"v":22,"text":"Repent therefore of this your wickedness, and pray God if perhaps the thought of your heart may be forgiven you.","heading":null},{"v":23,"text":"For I see that you are poisoned by bitterness and bound by iniquity.”","heading":null},{"v":24,"text":"Then Simon answered and said, “Pray to the Lord for me, that none of the things which you have spoken may come upon me.”","heading":null},{"v":25,"text":"So when they had testified and preached the word of the Lord, they returned to Jerusalem, preaching the gospel in many villages of the Samaritans.","heading":null},{"v":26,"text":"Now an angel of the Lord spoke to Philip, saying, “Arise and go toward the south along the road which goes down from Jerusalem to Gaza.” This is desert.","heading":"Christ Is Preached to an Ethiopian"},{"v":27,"text":"So he arose and went. And behold, a man of Ethiopia, a eunuch of great authority under Candace the queen of the Ethiopians, who had charge of all her treasury, and had come to Jerusalem to worship,","heading":null},{"v":28,"text":"was returning. And sitting in his chariot, he was reading Isaiah the prophet.","heading":null},{"v":29,"text":"Then the Spirit said to Philip, “Go near and overtake this chariot.”","heading":null},{"v":30,"text":"So Philip ran to him, and heard him reading the prophet Isaiah, and said, “Do you understand what you are reading?”","heading":null},{"v":31,"text":"And he said, “How can I, unless someone guides me?” And he asked Philip to come up and sit with him.","heading":null},{"v":32,"text":"The place in the Scripture which he read was this: “He was led as a sheep to the slaughter; And as a lamb before its shearer is silent, So He opened not His mouth.","heading":null},{"v":33,"text":"In His humiliation His justice was taken away, And who will declare His generation? For His life is taken from the earth.”","heading":null},{"v":34,"text":"So the eunuch answered Philip and said, “I ask you, of whom does the prophet say this, of himself or of some other man?”","heading":null},{"v":35,"text":"Then Philip opened his mouth, and beginning at this Scripture, preached Jesus to him.","heading":null},{"v":36,"text":"Now as they went down the road, they came to some water. And the eunuch said, “See, here is water. What hinders me from being baptized?”","heading":null},{"v":37,"text":"Then Philip said, “If you believe with all your heart, you may.” And he answered and said, “I believe that Jesus Christ is the Son of God.”","heading":null},{"v":38,"text":"So he commanded the chariot to stand still. And both Philip and the eunuch went down into the water, and he baptized him.","heading":null},{"v":39,"text":"Now when they came up out of the water, the Spirit of the Lord caught Philip away, so that the eunuch saw him no more; and he went on his way rejoicing.","heading":null},{"v":40,"text":"But Philip was found at Azotus. And passing through, he preached in all the cities till he came to Caesarea.","heading":null}],"days":[{"day":34,"week":7,"ref":"Acts 8:1-8","title":"Saul Persecutes the Church; Christ Is Preached in Samaria","start":1,"end":8},{"day":35,"week":7,"ref":"Acts 8:9-13","title":"The Sorcerer’s Profession of Faith","start":9,"end":13},{"day":36,"week":8,"ref":"Acts 8:14-25","title":"The Sorcerer’s Sin","start":14,"end":25},{"day":37,"week":8,"ref":"Acts 8:26-33","title":"Christ Is Preached to an Ethiopian","start":26,"end":33},{"day":38,"week":8,"ref":"Acts 8:34-40","title":"Christ Is Preached to an Ethiopian (continued)","start":34,"end":40}]},"9":{"chapter":9,"translation":"NKJV","verses":[{"v":1,"text":"Then Saul, still breathing threats and murder against the disciples of the Lord, went to the high priest","heading":null},{"v":2,"text":"and asked letters from him to the synagogues of Damascus, so that if he found any who were of the Way, whether men or women, he might bring them bound to Jerusalem.","heading":null},{"v":3,"text":"As he journeyed he came near Damascus, and suddenly a light shone around him from heaven.","heading":null},{"v":4,"text":"Then he fell to the ground, and heard a voice saying to him, “Saul, Saul, why are you persecuting Me?”","heading":null},{"v":5,"text":"And he said, “Who are You, Lord?” Then the Lord said, “I am Jesus, whom you are persecuting. It is hard for you to kick against the goads.”","heading":null},{"v":6,"text":"So he, trembling and astonished, said, “Lord, what do You want me to do?” Then the Lord said to him, “Arise and go into the city, and you will be told what you must do.”","heading":null},{"v":7,"text":"And the men who journeyed with him stood speechless, hearing a voice but seeing no one.","heading":null},{"v":8,"text":"Then Saul arose from the ground, and when his eyes were opened he saw no one. But they led him by the hand and brought him into Damascus.","heading":null},{"v":9,"text":"And he was three days without sight, and neither ate nor drank.","heading":null},{"v":10,"text":"Now there was a certain disciple at Damascus named Ananias; and to him the Lord said in a vision, “Ananias.” And he said, “Here I am, Lord.”","heading":"Ananias Baptizes Saul"},{"v":11,"text":"So the Lord said to him, “Arise and go to the street called Straight, and inquire at the house of Judas for one called Saul of Tarsus, for behold, he is praying.","heading":null},{"v":12,"text":"And in a vision he has seen a man named Ananias coming in and putting his hand on him, so that he might receive his sight.”","heading":null},{"v":13,"text":"Then Ananias answered, “Lord, I have heard from many about this man, how much harm he has done to Your saints in Jerusalem.","heading":null},{"v":14,"text":"And here he has authority from the chief priests to bind all who call on Your name.”","heading":null},{"v":15,"text":"But the Lord said to him, “Go, for he is a chosen vessel of Mine to bear My name before Gentiles, kings, and the children of Israel.","heading":null},{"v":16,"text":"For I will show him how many things he must suffer for My name’s sake.”","heading":null},{"v":17,"text":"And Ananias went his way and entered the house; and laying his hands on him he said, “Brother Saul, the Lord Jesus, who appeared to you on the road as you came, has sent me that you may receive your sight and be filled with the Holy Spirit.”","heading":null},{"v":18,"text":"Immediately there fell from his eyes something like scales, and he received his sight at once; and he arose and was baptized.","heading":null},{"v":19,"text":"So when he had received food, he was strengthened. Then Saul spent some days with the disciples at Damascus.","heading":null},{"v":20,"text":"Immediately he preached the Christ in the synagogues, that He is the Son of God.","heading":"Saul Preaches Christ"},{"v":21,"text":"Then all who heard were amazed, and said, “Is this not he who destroyed those who called on this name in Jerusalem, and has come here for that purpose, so that he might bring them bound to the chief priests?”","heading":null},{"v":22,"text":"But Saul increased all the more in strength, and confounded the Jews who dwelt in Damascus, proving that this Jesus is the Christ.","heading":null},{"v":23,"text":"Now after many days were past, the Jews plotted to kill him.","heading":"Saul Escapes Death"},{"v":24,"text":"But their plot became known to Saul. And they watched the gates day and night, to kill him.","heading":null},{"v":25,"text":"Then the disciples took him by night and let him down through the wall in a large basket.","heading":null},{"v":26,"text":"And when Saul had come to Jerusalem, he tried to join the disciples; but they were all afraid of him, and did not believe that he was a disciple.","heading":"Saul at Jerusalem"},{"v":27,"text":"But Barnabas took him and brought him to the apostles. And he declared to them how he had seen the Lord on the road, and that He had spoken to him, and how he had preached boldly at Damascus in the name of Jesus.","heading":null},{"v":28,"text":"So he was with them at Jerusalem, coming in and going out.","heading":null},{"v":29,"text":"And he spoke boldly in the name of the Lord Jesus and disputed against the Hellenists, but they attempted to kill him.","heading":null},{"v":30,"text":"When the brethren found out, they brought him down to Caesarea and sent him out to Tarsus.","heading":null},{"v":31,"text":"Then the churches throughout all Judea, Galilee, and Samaria had peace and were edified. And walking in the fear of the Lord and in the comfort of the Holy Spirit, they were multiplied.","heading":"The Church Prospers"},{"v":32,"text":"Now it came to pass, as Peter went through all parts of the country, that he also came down to the saints who dwelt in Lydda.","heading":"Aeneas Healed"},{"v":33,"text":"There he found a certain man named Aeneas, who had been bedridden eight years and was paralyzed.","heading":null},{"v":34,"text":"And Peter said to him, “Aeneas, Jesus the Christ heals you. Arise and make your bed.” Then he arose immediately.","heading":null},{"v":35,"text":"So all who dwelt at Lydda and Sharon saw him and turned to the Lord.","heading":null},{"v":36,"text":"At Joppa there was a certain disciple named Tabitha, which is translated Dorcas. This woman was full of good works and charitable deeds which she did.","heading":"Dorcas Restored to Life"},{"v":37,"text":"But it happened in those days that she became sick and died. When they had washed her, they laid her in an upper room.","heading":null},{"v":38,"text":"And since Lydda was near Joppa, and the disciples had heard that Peter was there, they sent two men to him, imploring him not to delay in coming to them.","heading":null},{"v":39,"text":"Then Peter arose and went with them. When he had come, they brought him to the upper room. And all the widows stood by him weeping, showing the tunics and garments which Dorcas had made while she was with them.","heading":null},{"v":40,"text":"But Peter put them all out, and knelt down and prayed. And turning to the body he said, “Tabitha, arise.” And she opened her eyes, and when she saw Peter she sat up.","heading":null},{"v":41,"text":"Then he gave her his hand and lifted her up; and when he had called the saints and widows, he presented her alive.","heading":null},{"v":42,"text":"And it became known throughout all Joppa, and many believed on the Lord.","heading":null},{"v":43,"text":"So it was that he stayed many days in Joppa with Simon, a tanner.","heading":null}],"days":[{"day":39,"week":8,"ref":"Acts 9:1-9","title":"The Damascus Road: Saul Converted","start":1,"end":9},{"day":40,"week":8,"ref":"Acts 9:10-19","title":"Ananias Baptized Saul","start":10,"end":19},{"day":41,"week":9,"ref":"Acts 9:20-25","title":"Saul Preaches Christ; Saul Escapes Death","start":20,"end":25},{"day":42,"week":9,"ref":"Acts 9:26-30","title":"Saul at Jerusalem","start":26,"end":30},{"day":43,"week":9,"ref":"Acts 9:31-35","title":"The Church Prospers; Aeneas Healed","start":31,"end":35},{"day":44,"week":9,"ref":"Acts 9:36-43","title":"Dorcas Restored to Life","start":36,"end":43}]},"10":{"chapter":10,"translation":"NKJV","verses":[{"v":1,"text":"There was a certain man in Caesarea called Cornelius, a centurion of what was called the Italian Regiment,","heading":null},{"v":2,"text":"a devout man and one who feared God with all his household, who gave alms generously to the people, and prayed to God always.","heading":null},{"v":3,"text":"About the ninth hour of the day he saw clearly in a vision an angel of God coming in and saying to him, “Cornelius!”","heading":null},{"v":4,"text":"And when he observed him, he was afraid, and said, “What is it, lord?” So he said to him, “Your prayers and your alms have come up for a memorial before God.","heading":null},{"v":5,"text":"Now send men to Joppa, and send for Simon whose surname is Peter.","heading":null},{"v":6,"text":"He is lodging with Simon, a tanner, whose house is by the sea. He will tell you what you must do.”","heading":null},{"v":7,"text":"And when the angel who spoke to him had departed, Cornelius called two of his household servants and a devout soldier from among those who waited on him continually.","heading":null},{"v":8,"text":"So when he had explained all these things to them, he sent them to Joppa.","heading":null},{"v":9,"text":"The next day, as they went on their journey and drew near the city, Peter went up on the housetop to pray, about the sixth hour.","heading":"Peter’s Vision"},{"v":10,"text":"Then he became very hungry and wanted to eat; but while they made ready, he fell into a trance","heading":null},{"v":11,"text":"and saw heaven opened and an object like a great sheet bound at the four corners, descending to him and let down to the earth.","heading":null},{"v":12,"text":"In it were all kinds of four-footed animals of the earth, wild beasts, creeping things, and birds of the air.","heading":null},{"v":13,"text":"And a voice came to him, “Rise, Peter; kill and eat.”","heading":null},{"v":14,"text":"But Peter said, “Not so, Lord! For I have never eaten anything common or unclean.”","heading":null},{"v":15,"text":"And a voice spoke to him again the second time, “What God has cleansed you must not call common.”","heading":null},{"v":16,"text":"This was done three times. And the object was taken up into heaven again.","heading":null},{"v":17,"text":"Now while Peter wondered within himself what this vision which he had seen meant, behold, the men who had been sent from Cornelius had made inquiry for Simon’s house, and stood before the gate.","heading":"Summoned to Caesarea"},{"v":18,"text":"And they called and asked whether Simon, whose surname was Peter, was lodging there.","heading":null},{"v":19,"text":"While Peter thought about the vision, the Spirit said to him, “Behold, three men are seeking you.","heading":null},{"v":20,"text":"Arise therefore, go down and go with them, doubting nothing; for I have sent them.”","heading":null},{"v":21,"text":"Then Peter went down to the men who had been sent to him from Cornelius, and said, “Yes, I am he whom you seek. For what reason have you come?”","heading":null},{"v":22,"text":"And they said, “Cornelius the centurion, a just man, one who fears God and has a good reputation among all the nation of the Jews, was divinely instructed by a holy angel to summon you to his house, and to hear words from you.”","heading":null},{"v":23,"text":"Then he invited them in and lodged them. On the next day Peter went away with them, and some brethren from Joppa accompanied him.","heading":null},{"v":24,"text":"And the following day they entered Caesarea. Now Cornelius was waiting for them, and had called together his relatives and close friends.","heading":"Peter Meets Cornelius"},{"v":25,"text":"As Peter was coming in, Cornelius met him and fell down at his feet and worshiped him.","heading":null},{"v":26,"text":"But Peter lifted him up, saying, “Stand up; I myself am also a man.”","heading":null},{"v":27,"text":"And as he talked with him, he went in and found many who had come together.","heading":null},{"v":28,"text":"Then he said to them, “You know how unlawful it is for a Jewish man to keep company with or go to one of another nation. But God has shown me that I should not call any man common or unclean.","heading":null},{"v":29,"text":"Therefore I came without objection as soon as I was sent for. I ask, then, for what reason have you sent for me?”","heading":null},{"v":30,"text":"So Cornelius said, “Four days ago I was fasting until this hour; and at the ninth hour I prayed in my house, and behold, a man stood before me in bright clothing,","heading":null},{"v":31,"text":"and said, ‘Cornelius, your prayer has been heard, and your alms are remembered in the sight of God.","heading":null},{"v":32,"text":"Send therefore to Joppa and call Simon here, whose surname is Peter. He is lodging in the house of Simon, a tanner, by the sea. When he comes, he will speak to you.’","heading":null},{"v":33,"text":"So I sent to you immediately, and you have done well to come. Now therefore, we are all present before God, to hear all the things commanded you by God.”","heading":null},{"v":34,"text":"Then Peter opened his mouth and said: “In truth I perceive that God shows no partiality.","heading":"Preaching to Cornelius’ Household"},{"v":35,"text":"But in every nation whoever fears Him and works righteousness is accepted by Him.","heading":null},{"v":36,"text":"The word which God sent to the children of Israel, preaching peace through Jesus Christ—He is Lord of all—","heading":null},{"v":37,"text":"that word you know, which was proclaimed throughout all Judea, and began from Galilee after the baptism which John preached:","heading":null},{"v":38,"text":"how God anointed Jesus of Nazareth with the Holy Spirit and with power, who went about doing good and healing all who were oppressed by the devil, for God was with Him.","heading":null},{"v":39,"text":"And we are witnesses of all things which He did both in the land of the Jews and in Jerusalem, whom they killed by hanging on a tree.","heading":null},{"v":40,"text":"Him God raised up on the third day, and showed Him openly,","heading":null},{"v":41,"text":"not to all the people, but to witnesses chosen before by God, even to us who ate and drank with Him after He arose from the dead.","heading":null},{"v":42,"text":"And He commanded us to preach to the people, and to testify that it is He who was ordained by God to be Judge of the living and the dead.","heading":null},{"v":43,"text":"To Him all the prophets witness that, through His name, whoever believes in Him will receive remission of sins.”","heading":null},{"v":44,"text":"While Peter was still speaking these words, the Holy Spirit fell upon all those who heard the word.","heading":"The Holy Spirit Falls on the Gentiles"},{"v":45,"text":"And those of the circumcision who believed were astonished, as many as came with Peter, because the gift of the Holy Spirit had been poured out on the Gentiles also.","heading":null},{"v":46,"text":"For they heard them speak with tongues and magnify God. Then Peter answered,","heading":null},{"v":47,"text":"“Can anyone forbid water, that these should not be baptized who have received the Holy Spirit just as we have? ”","heading":null},{"v":48,"text":"And he commanded them to be baptized in the name of the Lord. Then they asked him to stay a few days.","heading":null}],"days":[{"day":45,"week":9,"ref":"Acts 10:1-8","title":"Cornelius Sends a Delegation","start":1,"end":8},{"day":46,"week":10,"ref":"Acts 10:9-16","title":"Peter’s Vision","start":9,"end":16},{"day":47,"week":10,"ref":"Acts 10:17-23","title":"Summoned to Caesarea","start":17,"end":23},{"day":48,"week":10,"ref":"Acts 10:24-33","title":"Peter Meets Cornelius","start":24,"end":33},{"day":49,"week":10,"ref":"Acts 10:34-43","title":"Preaching to Cornelius’ Household","start":34,"end":43},{"day":50,"week":10,"ref":"Acts 10:44-48","title":"The Holy Spirit Falls on the Gentiles","start":44,"end":48}]},"11":{"chapter":11,"translation":"NKJV","verses":[{"v":1,"text":"Now the apostles and brethren who were in Judea heard that the Gentiles had also received the word of God.","heading":null},{"v":2,"text":"And when Peter came up to Jerusalem, those of the circumcision contended with him,","heading":null},{"v":3,"text":"saying, “You went in to uncircumcised men and ate with them!”","heading":null},{"v":4,"text":"But Peter explained it to them in order from the beginning, saying:","heading":null},{"v":5,"text":"“I was in the city of Joppa praying; and in a trance I saw a vision, an object descending like a great sheet, let down from heaven by four corners; and it came to me.","heading":null},{"v":6,"text":"When I observed it intently and considered, I saw four-footed animals of the earth, wild beasts, creeping things, and birds of the air.","heading":null},{"v":7,"text":"And I heard a voice saying to me, ‘Rise, Peter; kill and eat.’","heading":null},{"v":8,"text":"But I said, ‘Not so, Lord! For nothing common or unclean has at any time entered my mouth.’","heading":null},{"v":9,"text":"But the voice answered me again from heaven, ‘What God has cleansed you must not call common.’","heading":null},{"v":10,"text":"Now this was done three times, and all were drawn up again into heaven.","heading":null},{"v":11,"text":"At that very moment, three men stood before the house where I was, having been sent to me from Caesarea.","heading":null},{"v":12,"text":"Then the Spirit told me to go with them, doubting nothing. Moreover these six brethren accompanied me, and we entered the man’s house.","heading":null},{"v":13,"text":"And he told us how he had seen an angel standing in his house, who said to him, ‘Send men to Joppa, and call for Simon whose surname is Peter,","heading":null},{"v":14,"text":"who will tell you words by which you and all your household will be saved.’","heading":null},{"v":15,"text":"And as I began to speak, the Holy Spirit fell upon them, as upon us at the beginning.","heading":null},{"v":16,"text":"Then I remembered the word of the Lord, how He said, ‘John indeed baptized with water, but you shall be baptized with the Holy Spirit.’","heading":null},{"v":17,"text":"If therefore God gave them the same gift as He gave us when we believed on the Lord Jesus Christ, who was I that I could withstand God?”","heading":null},{"v":18,"text":"When they heard these things they became silent; and they glorified God, saying, “Then God has also granted to the Gentiles repentance to life.”","heading":null},{"v":19,"text":"Now those who were scattered after the persecution that arose over Stephen traveled as far as Phoenicia, Cyprus, and Antioch, preaching the word to no one but the Jews only.","heading":"Barnabas and Saul at Antioch"},{"v":20,"text":"But some of them were men from Cyprus and Cyrene, who, when they had come to Antioch, spoke to the Hellenists, preaching the Lord Jesus.","heading":null},{"v":21,"text":"And the hand of the Lord was with them, and a great number believed and turned to the Lord.","heading":null},{"v":22,"text":"Then news of these things came to the ears of the church in Jerusalem, and they sent out Barnabas to go as far as Antioch.","heading":null},{"v":23,"text":"When he came and had seen the grace of God, he was glad, and encouraged them all that with purpose of heart they should continue with the Lord.","heading":null},{"v":24,"text":"For he was a good man, full of the Holy Spirit and of faith. And a great many people were added to the Lord.","heading":null},{"v":25,"text":"Then Barnabas departed for Tarsus to seek Saul.","heading":null},{"v":26,"text":"And when he had found him, he brought him to Antioch. So it was that for a whole year they assembled with the church and taught a great many people. And the disciples were first called Christians in Antioch.","heading":null},{"v":27,"text":"And in these days prophets came from Jerusalem to Antioch.","heading":"Relief to Judea"},{"v":28,"text":"Then one of them, named Agabus, stood up and showed by the Spirit that there was going to be a great famine throughout all the world, which also happened in the days of Claudius Caesar.","heading":null},{"v":29,"text":"Then the disciples, each according to his ability, determined to send relief to the brethren dwelling in Judea.","heading":null},{"v":30,"text":"This they also did, and sent it to the elders by the hands of Barnabas and Saul.","heading":null}],"days":[{"day":51,"week":11,"ref":"Acts 11:1-8","title":"Peter Defends God’s Grace","start":1,"end":8},{"day":52,"week":11,"ref":"Acts 11:9-18","title":"Peter Defends God’s Grace (continued)","start":9,"end":18},{"day":53,"week":11,"ref":"Acts 11:19-26","title":"Barnabas and Saul at Antioch","start":19,"end":26},{"day":54,"week":11,"ref":"Acts 11:27-30","title":"Relief to Judea","start":27,"end":30}]},"12":{"chapter":12,"translation":"NKJV","verses":[{"v":1,"text":"Now about that time Herod the king stretched out his hand to harass some from the church.","heading":null},{"v":2,"text":"Then he killed James the brother of John with the sword.","heading":null},{"v":3,"text":"And because he saw that it pleased the Jews, he proceeded further to seize Peter also. Now it was during the Days of Unleavened Bread.","heading":null},{"v":4,"text":"So when he had arrested him, he put him in prison, and delivered him to four squads of soldiers to keep him, intending to bring him before the people after Passover.","heading":null},{"v":5,"text":"Peter was therefore kept in prison, but constant prayer was offered to God for him by the church.","heading":"Peter Freed from Prison"},{"v":6,"text":"And when Herod was about to bring him out, that night Peter was sleeping, bound with two chains between two soldiers; and the guards before the door were keeping the prison.","heading":null},{"v":7,"text":"Now behold, an angel of the Lord stood by him, and a light shone in the prison; and he struck Peter on the side and raised him up, saying, “Arise quickly!” And his chains fell off his hands.","heading":null},{"v":8,"text":"Then the angel said to him, “Gird yourself and tie on your sandals”; and so he did. And he said to him, “Put on your garment and follow me.”","heading":null},{"v":9,"text":"So he went out and followed him, and did not know that what was done by the angel was real, but thought he was seeing a vision.","heading":null},{"v":10,"text":"When they were past the first and the second guard posts, they came to the iron gate that leads to the city, which opened to them of its own accord; and they went out and went down one street, and immediately the angel departed from him.","heading":null},{"v":11,"text":"And when Peter had come to himself, he said, “Now I know for certain that the Lord has sent His angel, and has delivered me from the hand of Herod and from all the expectation of the Jewish people.”","heading":null},{"v":12,"text":"So, when he had considered this, he came to the house of Mary, the mother of John whose surname was Mark, where many were gathered together praying.","heading":null},{"v":13,"text":"And as Peter knocked at the door of the gate, a girl named Rhoda came to answer.","heading":null},{"v":14,"text":"When she recognized Peter’s voice, because of her gladness she did not open the gate, but ran in and announced that Peter stood before the gate.","heading":null},{"v":15,"text":"But they said to her, “You are beside yourself!” Yet she kept insisting that it was so. So they said, “It is his angel.”","heading":null},{"v":16,"text":"Now Peter continued knocking; and when they opened the door and saw him, they were astonished.","heading":null},{"v":17,"text":"But motioning to them with his hand to keep silent, he declared to them how the Lord had brought him out of the prison. And he said, “Go, tell these things to James and to the brethren.” And he departed and went to another place.","heading":null},{"v":18,"text":"Then, as soon as it was day, there was no small stir among the soldiers about what had become of Peter.","heading":null},{"v":19,"text":"But when Herod had searched for him and not found him, he examined the guards and commanded that they should be put to death. And he went down from Judea to Caesarea, and stayed there.","heading":null},{"v":20,"text":"Now Herod had been very angry with the people of Tyre and Sidon; but they came to him with one accord, and having made Blastus the king’s personal aide their friend, they asked for peace, because their country was supplied with food by the king’s country.","heading":"Herod’s Violent Death"},{"v":21,"text":"So on a set day Herod, arrayed in royal apparel, sat on his throne and gave an oration to them.","heading":null},{"v":22,"text":"And the people kept shouting, “The voice of a god and not of a man!”","heading":null},{"v":23,"text":"Then immediately an angel of the Lord struck him, because he did not give glory to God. And he was eaten by worms and died.","heading":null},{"v":24,"text":"But the word of God grew and multiplied.","heading":null},{"v":25,"text":"And Barnabas and Saul returned from Jerusalem when they had fulfilled their ministry, and they also took with them John whose surname was Mark.","heading":"Barnabas and Saul Appointed"}],"days":[{"day":55,"week":11,"ref":"Acts 12:1-4","title":"Herod’s Violence to the Church","start":1,"end":4},{"day":56,"week":12,"ref":"Acts 12:5-10","title":"Peter Freed from Prison","start":5,"end":10},{"day":57,"week":12,"ref":"Acts 12:11-19","title":"Peter Freed from Prison (continued)","start":11,"end":19},{"day":58,"week":12,"ref":"Acts 12:20-25","title":"Herod’s Violent Death; Barnabas and Saul Appointed","start":20,"end":25}]},"13":{"chapter":13,"translation":"NKJV","verses":[{"v":1,"text":"Now in the church that was at Antioch there were certain prophets and teachers: Barnabas, Simeon who was called Niger, Lucius of Cyrene, Manaen who had been brought up with Herod the tetrarch, and Saul.","heading":null},{"v":2,"text":"As they ministered to the Lord and fasted, the Holy Spirit said, “Now separate to Me Barnabas and Saul for the work to which I have called them.”","heading":null},{"v":3,"text":"Then, having fasted and prayed, and laid hands on them, they sent them away.","heading":null},{"v":4,"text":"So, being sent out by the Holy Spirit, they went down to Seleucia, and from there they sailed to Cyprus.","heading":"Preaching in Cyprus"},{"v":5,"text":"And when they arrived in Salamis, they preached the word of God in the synagogues of the Jews. They also had John as their assistant.","heading":null},{"v":6,"text":"Now when they had gone through the island to Paphos, they found a certain sorcerer, a false prophet, a Jew whose name was Bar-Jesus,","heading":null},{"v":7,"text":"who was with the proconsul, Sergius Paulus, an intelligent man. This man called for Barnabas and Saul and sought to hear the word of God.","heading":null},{"v":8,"text":"But Elymas the sorcerer (for so his name is translated) withstood them, seeking to turn the proconsul away from the faith.","heading":null},{"v":9,"text":"Then Saul, who also is called Paul, filled with the Holy Spirit, looked intently at him","heading":null},{"v":10,"text":"and said, “O full of all deceit and all fraud, you son of the devil, you enemy of all righteousness, will you not cease perverting the straight ways of the Lord?","heading":null},{"v":11,"text":"And now, indeed, the hand of the Lord is upon you, and you shall be blind, not seeing the sun for a time.” And immediately a dark mist fell on him, and he went around seeking someone to lead him by the hand.","heading":null},{"v":12,"text":"Then the proconsul believed, when he saw what had been done, being astonished at the teaching of the Lord.","heading":null},{"v":13,"text":"Now when Paul and his party set sail from Paphos, they came to Perga in Pamphylia; and John, departing from them, returned to Jerusalem.","heading":"At Antioch in Pisidia"},{"v":14,"text":"But when they departed from Perga, they came to Antioch in Pisidia, and went into the synagogue on the Sabbath day and sat down.","heading":null},{"v":15,"text":"And after the reading of the Law and the Prophets, the rulers of the synagogue sent to them, saying, “Men and brethren, if you have any word of exhortation for the people, say on.”","heading":null},{"v":16,"text":"Then Paul stood up, and motioning with his hand said, “Men of Israel, and you who fear God, listen:","heading":null},{"v":17,"text":"The God of this people Israel chose our fathers, and exalted the people when they dwelt as strangers in the land of Egypt, and with an uplifted arm He brought them out of it.","heading":null},{"v":18,"text":"Now for a time of about forty years He put up with their ways in the wilderness.","heading":null},{"v":19,"text":"And when He had destroyed seven nations in the land of Canaan, He distributed their land to them by allotment.","heading":null},{"v":20,"text":"“After that He gave them judges for about four hundred and fifty years, until Samuel the prophet.","heading":null},{"v":21,"text":"And afterward they asked for a king; so God gave them Saul the son of Kish, a man of the tribe of Benjamin, for forty years.","heading":null},{"v":22,"text":"And when He had removed him, He raised up for them David as king, to whom also He gave testimony and said, ‘I have found David the son of Jesse, a man after My own heart, who will do all My will.’","heading":null},{"v":23,"text":"From this man’s seed, according to the promise, God raised up for Israel a Savior—Jesus—","heading":null},{"v":24,"text":"after John had first preached, before His coming, the baptism of repentance to all the people of Israel.","heading":null},{"v":25,"text":"And as John was finishing his course, he said, ‘Who do you think I am? I am not He. But behold, there comes One after me, the sandals of whose feet I am not worthy to loose.’","heading":null},{"v":26,"text":"“Men and brethren, sons of the family of Abraham, and those among you who fear God, to you the word of this salvation has been sent.","heading":null},{"v":27,"text":"For those who dwell in Jerusalem, and their rulers, because they did not know Him, nor even the voices of the Prophets which are read every Sabbath, have fulfilled them in condemning Him.","heading":null},{"v":28,"text":"And though they found no cause for death in Him, they asked Pilate that He should be put to death.","heading":null},{"v":29,"text":"Now when they had fulfilled all that was written concerning Him, they took Him down from the tree and laid Him in a tomb.","heading":null},{"v":30,"text":"But God raised Him from the dead.","heading":null},{"v":31,"text":"He was seen for many days by those who came up with Him from Galilee to Jerusalem, who are His witnesses to the people.","heading":null},{"v":32,"text":"And we declare to you glad tidings—that promise which was made to the fathers.","heading":null},{"v":33,"text":"God has fulfilled this for us their children, in that He has raised up Jesus. As it is also written in the second Psalm: ‘You are My Son, Today I have begotten You.’","heading":null},{"v":34,"text":"And that He raised Him from the dead, no more to return to corruption, He has spoken thus: ‘I will give you the sure mercies of David.’","heading":null},{"v":35,"text":"Therefore He also says in another Psalm: ‘You will not allow Your Holy One to see corruption.’","heading":null},{"v":36,"text":"“For David, after he had served his own generation by the will of God, fell asleep, was buried with his fathers, and saw corruption;","heading":null},{"v":37,"text":"but He whom God raised up saw no corruption.","heading":null},{"v":38,"text":"Therefore let it be known to you, brethren, that through this Man is preached to you the forgiveness of sins;","heading":null},{"v":39,"text":"and by Him everyone who believes is justified from all things from which you could not be justified by the law of Moses.","heading":null},{"v":40,"text":"Beware therefore, lest what has been spoken in the prophets come upon you:","heading":null},{"v":41,"text":"‘Behold, you despisers, Marvel and perish! For I work a work in your days, A work which you will by no means believe, Though one were to declare it to you.’ ”","heading":null},{"v":42,"text":"So when the Jews went out of the synagogue, the Gentiles begged that these words might be preached to them the next Sabbath.","heading":"Blessing and Conflict at Antioch"},{"v":43,"text":"Now when the congregation had broken up, many of the Jews and devout proselytes followed Paul and Barnabas, who, speaking to them, persuaded them to continue in the grace of God.","heading":null},{"v":44,"text":"On the next Sabbath almost the whole city came together to hear the word of God.","heading":null},{"v":45,"text":"But when the Jews saw the multitudes, they were filled with envy; and contradicting and blaspheming, they opposed the things spoken by Paul.","heading":null},{"v":46,"text":"Then Paul and Barnabas grew bold and said, “It was necessary that the word of God should be spoken to you first; but since you reject it, and judge yourselves unworthy of everlasting life, behold, we turn to the Gentiles.","heading":null},{"v":47,"text":"For so the Lord has commanded us: ‘I have set you as a light to the Gentiles, That you should be for salvation to the ends of the earth.’ ”","heading":null},{"v":48,"text":"Now when the Gentiles heard this, they were glad and glorified the word of the Lord. And as many as had been appointed to eternal life believed.","heading":null},{"v":49,"text":"And the word of the Lord was being spread throughout all the region.","heading":null},{"v":50,"text":"But the Jews stirred up the devout and prominent women and the chief men of the city, raised up persecution against Paul and Barnabas, and expelled them from their region.","heading":null},{"v":51,"text":"But they shook off the dust from their feet against them, and came to Iconium.","heading":null},{"v":52,"text":"And the disciples were filled with joy and with the Holy Spirit.","heading":null}],"days":[{"day":59,"week":12,"ref":"Acts 13:1-12","title":"Barnabas and Saul Appointed; Preaching in Cyprus","start":1,"end":12},{"day":60,"week":12,"ref":"Acts 13:13-25","title":"At Antioch in Pisidia","start":13,"end":25},{"day":61,"week":13,"ref":"Acts 13:26-41","title":"At Antioch in Pisidia (continued)","start":26,"end":41},{"day":62,"week":13,"ref":"Acts 13:42-52","title":"Blessing and Conflict at Antioch","start":42,"end":52}]},"14":{"chapter":14,"translation":"NKJV","verses":[{"v":1,"text":"Now it happened in Iconium that they went together to the synagogue of the Jews, and so spoke that a great multitude both of the Jews and of the Greeks believed.","heading":null},{"v":2,"text":"But the unbelieving Jews stirred up the Gentiles and poisoned their minds against the brethren.","heading":null},{"v":3,"text":"Therefore they stayed there a long time, speaking boldly in the Lord, who was bearing witness to the word of His grace, granting signs and wonders to be done by their hands.","heading":null},{"v":4,"text":"But the multitude of the city was divided: part sided with the Jews, and part with the apostles.","heading":null},{"v":5,"text":"And when a violent attempt was made by both the Gentiles and Jews, with their rulers, to abuse and stone them,","heading":null},{"v":6,"text":"they became aware of it and fled to Lystra and Derbe, cities of Lycaonia, and to the surrounding region.","heading":null},{"v":7,"text":"And they were preaching the gospel there.","heading":null},{"v":8,"text":"And in Lystra a certain man without strength in his feet was sitting, a cripple from his mother’s womb, who had never walked.","heading":"Idolatry at Lystra"},{"v":9,"text":"This man heard Paul speaking. Paul, observing him intently and seeing that he had faith to be healed,","heading":null},{"v":10,"text":"said with a loud voice, “Stand up straight on your feet!” And he leaped and walked.","heading":null},{"v":11,"text":"Now when the people saw what Paul had done, they raised their voices, saying in the Lycaonian language, “The gods have come down to us in the likeness of men!”","heading":null},{"v":12,"text":"And Barnabas they called Zeus, and Paul, Hermes, because he was the chief speaker.","heading":null},{"v":13,"text":"Then the priest of Zeus, whose temple was in front of their city, brought oxen and garlands to the gates, intending to sacrifice with the multitudes.","heading":null},{"v":14,"text":"But when the apostles Barnabas and Paul heard this, they tore their clothes and ran in among the multitude, crying out","heading":null},{"v":15,"text":"and saying, “Men, why are you doing these things? We also are men with the same nature as you, and preach to you that you should turn from these useless things to the living God, who made the heaven, the earth, the sea, and all things that are in them,","heading":null},{"v":16,"text":"who in bygone generations allowed all nations to walk in their own ways.","heading":null},{"v":17,"text":"Nevertheless He did not leave Himself without witness, in that He did good, gave us rain from heaven and fruitful seasons, filling our hearts with food and gladness.”","heading":null},{"v":18,"text":"And with these sayings they could scarcely restrain the multitudes from sacrificing to them.","heading":null},{"v":19,"text":"Then Jews from Antioch and Iconium came there; and having persuaded the multitudes, they stoned Paul and dragged him out of the city, supposing him to be dead.","heading":"Stoning, Escape to Derbe"},{"v":20,"text":"However, when the disciples gathered around him, he rose up and went into the city. And the next day he departed with Barnabas to Derbe.","heading":null},{"v":21,"text":"And when they had preached the gospel to that city and made many disciples, they returned to Lystra, Iconium, and Antioch,","heading":"Strengthening the Converts"},{"v":22,"text":"strengthening the souls of the disciples, exhorting them to continue in the faith, and saying, “We must through many tribulations enter the kingdom of God.”","heading":null},{"v":23,"text":"So when they had appointed elders in every church, and prayed with fasting, they commended them to the Lord in whom they had believed.","heading":null},{"v":24,"text":"And after they had passed through Pisidia, they came to Pamphylia.","heading":null},{"v":25,"text":"Now when they had preached the word in Perga, they went down to Attalia.","heading":null},{"v":26,"text":"From there they sailed to Antioch, where they had been commended to the grace of God for the work which they had completed.","heading":null},{"v":27,"text":"Now when they had come and gathered the church together, they reported all that God had done with them, and that He had opened the door of faith to the Gentiles.","heading":null},{"v":28,"text":"So they stayed there a long time with the disciples.","heading":null}],"days":[{"day":63,"week":13,"ref":"Acts 14:1-7","title":"At Iconium","start":1,"end":7},{"day":64,"week":13,"ref":"Acts 14:8-18","title":"Idolatry at Lystra","start":8,"end":18},{"day":65,"week":13,"ref":"Acts 14:19-28","title":"Stoning,Escape to Derbe; Strengthening the Converts","start":19,"end":28}]},"15":{"chapter":15,"translation":"NKJV","verses":[{"v":1,"text":"And certain men came down from Judea and taught the brethren, “Unless you are circumcised according to the custom of Moses, you cannot be saved.”","heading":null},{"v":2,"text":"Therefore, when Paul and Barnabas had no small dissension and dispute with them, they determined that Paul and Barnabas and certain others of them should go up to Jerusalem, to the apostles and elders, about this question.","heading":null},{"v":3,"text":"So, being sent on their way by the church, they passed through Phoenicia and Samaria, describing the conversion of the Gentiles; and they caused great joy to all the brethren.","heading":null},{"v":4,"text":"And when they had come to Jerusalem, they were received by the church and the apostles and the elders; and they reported all things that God had done with them.","heading":null},{"v":5,"text":"But some of the sect of the Pharisees who believed rose up, saying, “It is necessary to circumcise them, and to command them to keep the law of Moses.”","heading":null},{"v":6,"text":"Now the apostles and elders came together to consider this matter.","heading":"The Jerusalem Council"},{"v":7,"text":"And when there had been much dispute, Peter rose up and said to them: “Men and brethren, you know that a good while ago God chose among us, that by my mouth the Gentiles should hear the word of the gospel and believe.","heading":null},{"v":8,"text":"So God, who knows the heart, acknowledged them by giving them the Holy Spirit, just as He did to us,","heading":null},{"v":9,"text":"and made no distinction between us and them, purifying their hearts by faith.","heading":null},{"v":10,"text":"Now therefore, why do you test God by putting a yoke on the neck of the disciples which neither our fathers nor we were able to bear?","heading":null},{"v":11,"text":"But we believe that through the grace of the Lord Jesus Christ we shall be saved in the same manner as they.”","heading":null},{"v":12,"text":"Then all the multitude kept silent and listened to Barnabas and Paul declaring how many miracles and wonders God had worked through them among the Gentiles.","heading":null},{"v":13,"text":"And after they had become silent, James answered, saying, “Men and brethren, listen to me:","heading":null},{"v":14,"text":"Simon has declared how God at the first visited the Gentiles to take out of them a people for His name.","heading":null},{"v":15,"text":"And with this the words of the prophets agree, just as it is written:","heading":null},{"v":16,"text":"‘After this I will return And will rebuild the tabernacle of David, which has fallen down; I will rebuild its ruins, And I will set it up;","heading":null},{"v":17,"text":"So that the rest of mankind may seek the LORD, Even all the Gentiles who are called by My name, Says the LORD who does all these things.’","heading":null},{"v":18,"text":"“Known to God from eternity are all His works.","heading":null},{"v":19,"text":"Therefore I judge that we should not trouble those from among the Gentiles who are turning to God,","heading":null},{"v":20,"text":"but that we write to them to abstain from things polluted by idols, from sexual immorality, from things strangled, and from blood.","heading":null},{"v":21,"text":"For Moses has had throughout many generations those who preach him in every city, being read in the synagogues every Sabbath.”","heading":null},{"v":22,"text":"Then it pleased the apostles and elders, with the whole church, to send chosen men of their own company to Antioch with Paul and Barnabas, namely, Judas who was also named Barsabas, and Silas, leading men among the brethren.","heading":"The Jerusalem Decree"},{"v":23,"text":"They wrote this letter by them: The apostles, the elders, and the brethren, To the brethren who are of the Gentiles in Antioch, Syria, and Cilicia: Greetings.","heading":null},{"v":24,"text":"Since we have heard that some who went out from us have troubled you with words, unsettling your souls, saying, “ You must be circumcised and keep the law”—to whom we gave no such commandment—","heading":null},{"v":25,"text":"it seemed good to us, being assembled with one accord, to send chosen men to you with our beloved Barnabas and Paul,","heading":null},{"v":26,"text":"men who have risked their lives for the name of our Lord Jesus Christ.","heading":null},{"v":27,"text":"We have therefore sent Judas and Silas, who will also report the same things by word of mouth.","heading":null},{"v":28,"text":"For it seemed good to the Holy Spirit, and to us, to lay upon you no greater burden than these necessary things:","heading":null},{"v":29,"text":"that you abstain from things offered to idols, from blood, from things strangled, and from sexual immorality. If you keep yourselves from these, you will do well. Farewell.","heading":null},{"v":30,"text":"So when they were sent off, they came to Antioch; and when they had gathered the multitude together, they delivered the letter.","heading":"Continuing Ministry in Syria"},{"v":31,"text":"When they had read it, they rejoiced over its encouragement.","heading":null},{"v":32,"text":"Now Judas and Silas, themselves being prophets also, exhorted and strengthened the brethren with many words.","heading":null},{"v":33,"text":"And after they had stayed there for a time, they were sent back with greetings from the brethren to the apostles.","heading":null},{"v":34,"text":"However, it seemed good to Silas to remain there.","heading":null},{"v":35,"text":"Paul and Barnabas also remained in Antioch, teaching and preaching the word of the Lord, with many others also.","heading":null},{"v":36,"text":"Then after some days Paul said to Barnabas, “Let us now go back and visit our brethren in every city where we have preached the word of the Lord, and see how they are doing.”","heading":"Division over John Mark"},{"v":37,"text":"Now Barnabas was determined to take with them John called Mark.","heading":null},{"v":38,"text":"But Paul insisted that they should not take with them the one who had departed from them in Pamphylia, and had not gone with them to the work.","heading":null},{"v":39,"text":"Then the contention became so sharp that they parted from one another. And so Barnabas took Mark and sailed to Cyprus;","heading":null},{"v":40,"text":"but Paul chose Silas and departed, being commended by the brethren to the grace of God.","heading":null},{"v":41,"text":"And he went through Syria and Cilicia, strengthening the churches.","heading":null}],"days":[{"day":66,"week":14,"ref":"Acts 15:1-5","title":"Conflict over Circumcision","start":1,"end":5},{"day":67,"week":14,"ref":"Acts 15:6-21","title":"The Jerusalem Council","start":6,"end":21},{"day":68,"week":14,"ref":"Acts 15:22-29","title":"The Jerusalem Decree","start":22,"end":29},{"day":69,"week":14,"ref":"Acts 15:30-41","title":"Continuing Ministry in Syria; Division over John Mark","start":30,"end":41}]},"16":{"chapter":16,"translation":"NKJV","verses":[{"v":1,"text":"Then he came to Derbe and Lystra. And behold, a certain disciple was there, named Timothy, the son of a certain Jewish woman who believed, but his father was Greek.","heading":null},{"v":2,"text":"He was well spoken of by the brethren who were at Lystra and Iconium.","heading":null},{"v":3,"text":"Paul wanted to have him go on with him. And he took him and circumcised him because of the Jews who were in that region, for they all knew that his father was Greek.","heading":null},{"v":4,"text":"And as they went through the cities, they delivered to them the decrees to keep, which were determined by the apostles and elders at Jerusalem.","heading":null},{"v":5,"text":"So the churches were strengthened in the faith, and increased in number daily.","heading":null},{"v":6,"text":"Now when they had gone through Phrygia and the region of Galatia, they were forbidden by the Holy Spirit to preach the word in Asia.","heading":"The Macedonian Call"},{"v":7,"text":"After they had come to Mysia, they tried to go into Bithynia, but the Spirit did not permit them.","heading":null},{"v":8,"text":"So passing by Mysia, they came down to Troas.","heading":null},{"v":9,"text":"And a vision appeared to Paul in the night. A man of Macedonia stood and pleaded with him, saying, “Come over to Macedonia and help us.”","heading":null},{"v":10,"text":"Now after he had seen the vision, immediately we sought to go to Macedonia, concluding that the Lord had called us to preach the gospel to them.","heading":null},{"v":11,"text":"Therefore, sailing from Troas, we ran a straight course to Samothrace, and the next day came to Neapolis,","heading":"Lydia Baptized at Philippi"},{"v":12,"text":"and from there to Philippi, which is the foremost city of that part of Macedonia, a colony. And we were staying in that city for some days.","heading":null},{"v":13,"text":"And on the Sabbath day we went out of the city to the riverside, where prayer was customarily made; and we sat down and spoke to the women who met there.","heading":null},{"v":14,"text":"Now a certain woman named Lydia heard us. She was a seller of purple from the city of Thyatira, who worshiped God. The Lord opened her heart to heed the things spoken by Paul.","heading":null},{"v":15,"text":"And when she and her household were baptized, she begged us, saying, “If you have judged me to be faithful to the Lord, come to my house and stay.” So she persuaded us.","heading":null},{"v":16,"text":"Now it happened, as we went to prayer, that a certain slave girl possessed with a spirit of divination met us, who brought her masters much profit by fortune-telling.","heading":"Paul and Silas Imprisoned"},{"v":17,"text":"This girl followed Paul and us, and cried out, saying, “These men are the servants of the Most High God, who proclaim to us the way of salvation.”","heading":null},{"v":18,"text":"And this she did for many days. But Paul, greatly annoyed, turned and said to the spirit, “I command you in the name of Jesus Christ to come out of her.” And he came out that very hour.","heading":null},{"v":19,"text":"But when her masters saw that their hope of profit was gone, they seized Paul and Silas and dragged them into the marketplace to the authorities.","heading":null},{"v":20,"text":"And they brought them to the magistrates, and said, “These men, being Jews, exceedingly trouble our city;","heading":null},{"v":21,"text":"and they teach customs which are not lawful for us, being Romans, to receive or observe.”","heading":null},{"v":22,"text":"Then the multitude rose up together against them; and the magistrates tore off their clothes and commanded them to be beaten with rods.","heading":null},{"v":23,"text":"And when they had laid many stripes on them, they threw them into prison, commanding the jailer to keep them securely.","heading":null},{"v":24,"text":"Having received such a charge, he put them into the inner prison and fastened their feet in the stocks.","heading":null},{"v":25,"text":"But at midnight Paul and Silas were praying and singing hymns to God, and the prisoners were listening to them.","heading":"The Philippian Jailer Saved"},{"v":26,"text":"Suddenly there was a great earthquake, so that the foundations of the prison were shaken; and immediately all the doors were opened and everyone’s chains were loosed.","heading":null},{"v":27,"text":"And the keeper of the prison, awaking from sleep and seeing the prison doors open, supposing the prisoners had fled, drew his sword and was about to kill himself.","heading":null},{"v":28,"text":"But Paul called with a loud voice, saying, “Do yourself no harm, for we are all here.”","heading":null},{"v":29,"text":"Then he called for a light, ran in, and fell down trembling before Paul and Silas.","heading":null},{"v":30,"text":"And he brought them out and said, “Sirs, what must I do to be saved?”","heading":null},{"v":31,"text":"So they said, “Believe on the Lord Jesus Christ, and you will be saved, you and your household.”","heading":null},{"v":32,"text":"Then they spoke the word of the Lord to him and to all who were in his house.","heading":null},{"v":33,"text":"And he took them the same hour of the night and washed their stripes. And immediately he and all his family were baptized.","heading":null},{"v":34,"text":"Now when he had brought them into his house, he set food before them; and he rejoiced, having believed in God with all his household.","heading":null},{"v":35,"text":"And when it was day, the magistrates sent the officers, saying, “Let those men go.”","heading":"Paul Refuses to Depart Secretly"},{"v":36,"text":"So the keeper of the prison reported these words to Paul, saying, “The magistrates have sent to let you go. Now therefore depart, and go in peace.”","heading":null},{"v":37,"text":"But Paul said to them, “They have beaten us openly, uncondemned Romans, and have thrown us into prison. And now do they put us out secretly? No indeed! Let them come themselves and get us out.”","heading":null},{"v":38,"text":"And the officers told these words to the magistrates, and they were afraid when they heard that they were Romans.","heading":null},{"v":39,"text":"Then they came and pleaded with them and brought them out, and asked them to depart from the city.","heading":null},{"v":40,"text":"So they went out of the prison and entered the house of Lydia; and when they had seen the brethren, they encouraged them and departed.","heading":null}],"days":[{"day":70,"week":14,"ref":"Acts 16:1-10","title":"Timothy Joins Paul and Silas; The Macedonian Call","start":1,"end":10},{"day":71,"week":15,"ref":"Acts 16:11-15","title":"Lydia Baptized at Philippi","start":11,"end":15},{"day":72,"week":15,"ref":"Acts 16:16-24","title":"Paul and Silas Imprisoned","start":16,"end":24},{"day":73,"week":15,"ref":"Acts 16:25-34","title":"The Philippian Jailer Saved","start":25,"end":34},{"day":74,"week":15,"ref":"Acts 16:35-40","title":"Paul Refuses to Depart Secretly","start":35,"end":40}]}};

